pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initialMinSum, uint256 incrementAmount, uint256 putAmount, uint256 collectAmount) public {
        // Keep initialMinSum in admissible range (uint256)
        // Ensure incrementAmount is non-zero to trigger the mutation difference
        vm.assume(incrementAmount > 0);
        // Ensure collectAmount is non-zero and putAmount is enough for a meaningful test
        vm.assume(collectAmount > 0);
        vm.assume(putAmount >= collectAmount);
        // Bound to avoid overflow issues in Solidity 0.8.x (though this isn't about overflow, keep reasonable)
        initialMinSum = bound(initialMinSum, 0, type(uint256).max - incrementAmount);
        putAmount = bound(putAmount, collectAmount, type(uint256).max);

        // Setup: initialize and set MinSum
        c.SetMinSum(initialMinSum);
        c.Initialized();

        // Record MinSum before any further SetMinSum calls
        uint256 minSumBefore = c.MinSum();

        // Call SetMinSum with incrementAmount (this is where the mutant differs)
        c.SetMinSum(incrementAmount);

        // Now put some funds to enable Collect later
        address user = address(0x1234);
        vm.deal(user, putAmount);
        vm.prank(user);
        c.Put{value: putAmount}(0);

        // Warp past unlock time
        vm.warp(block.timestamp + 1);

        // Collect
        vm.prank(user);
        c.Collect(collectAmount);

        // After Collect, MinSum should still equal minSumBefore (reference: MinSum unchanged after initialization)
        // Bug breaks this by adding _val to MinSum in SetMinSum
        assertEq(c.MinSum(), minSumBefore);
    }
}

