pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 initMin, uint256 extraVal) public {
        // 1. Bound values to keep arithmetic within reasonable limits
        initMin = bound(initMin, 0, type(uint128).max);
        extraVal = bound(extraVal, 0, type(uint128).max);
        vm.assume(initMin + extraVal <= type(uint256).max);

        // 2. Initialize contract and set initial MinSum
        address log = address(new LogFile());
        c.SetLogFile(log);
        c.SetMinSum(initMin);
        c.Initialized();

        // Record initial MinSum after setup
        uint256 expectedMin = c.MinSum();

        // 3. Call SetMinSum again – reference does nothing (or reverts), buggy increases it
        vm.prank(address(0x1));
        try c.SetMinSum(extraVal) {} catch {}

        // 4. Assert that MinSum still equals the initial value in reference
        assertEq(c.MinSum(), expectedMin);
    }
}

