import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 minSum, uint256 extraCall) public {
        vm.assume(minSum > 0);
        vm.assume(extraCall <= 10);
        // Set up the log file so the contract doesn't revert on a missing Log
        LogFile log = new LogFile();
        c.SetLogFile(address(log));
        c.SetMinSum(minSum);
        c.Initialized();
        // Call SetMinSum again — the reference ignores it (reverts because initialized),
        // but in the mutant it may succeed if the revert condition is bypassed?
        // Actually, the reference reverts after initialization, so we check whether
        // MinSum stays the same even after attempted calls vs. the mutant increasing it.
        // To expose the difference we need the mutant to NOT revert, so we make extra calls
        // BEFORE initialization, but the invariant must hold afterward.
        // We'll call SetMinSum multiple times before initialization with different values
        // and check that MinSum is exactly the first set value.
        uint256 firstSet = minSum;
        c.SetMinSum(firstSet);
        // additional calls with different values (fuzzed)
        for (uint i = 0; i < extraCall; i++) {
            c.SetMinSum(firstSet + i + 1);
        }
        c.SetLogFile(address(log));
        c.Initialized();
        assertTrue(c.MinSum() == firstSet);
    }
}

