pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address _log, address _sender, uint256 _am, uint256 _lockTime) public {
        // vm.assume reasonable domains
        vm.assume(_sender != address(0));
        vm.assume(_am > 0);
        vm.assume(_lockTime > 0);

        // Initialize the contract
        c.Initialized();

        // Call SetLogFile with fuzzed _log
        c.SetLogFile(_log);

        // Prepare sender: prank and deposit with lockTime
        vm.deal(_sender, _am + 1 ether);
        vm.startPrank(_sender);

        // Put some value (this also calls Log.AddMessage internally)
        c.Put{value: _am}(_lockTime);

        vm.stopPrank();

        // After Put, the correct contract should have logged via Log.AddMessage.
        // The buggy contract's Log is zero-address, which would revert on Put.
        // The invariant: calling Put never reverts when Log is set to a valid address,
        // but for zero-address Log, it reverts. We can't directly tell which occurred without observing state.
        // Better: look at Acc balance of sender to see if Put succeeded.
        // In correct contract, Put always succeeds; in buggy contract, Put reverts.
        // So invariant: After SetLogFile and a Put, sender's Acc.balance equals _am.
        // Buggy: Put reverts, so balance remains 0.
        (bool success,) = address(c).call(abi.encodeWithSignature("Acc(address)", _sender));
        // Actually Acc is a mapping so we need to access the getter for a public mapping: c.Acc(_sender)
        uint256 bal;
        try c.Acc(_sender) returns (C.Holder memory holder) {
            bal = holder.balance;
        } catch {
            bal = 0;
        }
        // In correct contract, bal == _am, because Put succeeded.
        // In buggy, Put reverted, so bal == 0.
        assertTrue(bal == _am);
    }
}

