        vm.assume(_addrBefore != address(0) && _addrAfter != address(0));
        vm.assume(_addrBefore != _addrAfter);

        // Initialize, then set Log to _addrBefore
        c.Initialized();
        c.SetLogFile(_addrBefore);

        // Now attempt a reverted pre-initialization call that will not finalize (rollback impossible)
        // To simulate a fresh attempt before initialization in the same transaction,
        // we deploy a new C instance to isolate the pre-initialized state change
