        address _third = address(uint160(uint256(keccak256(abi.encodePacked(_addrBefore, _addrAfter)))));
        vm.assume(_third != address(0) && _third != _addrBefore && _third != _addrAfter);
        fresh.Initialized();
        fresh.SetLogFile(_third);
        assertTrue(address(fresh.Log()) == _third);
    }
}

