    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 lockTime1, uint256 lockTime2, uint256 amount1, uint256 amount2, uint256 collectAmt, address actor) public {
        // Restrict to admissible domain: non-zero times reasonable for block.timestamp arithmetic, amounts that don't overflow
        vm.assume(actor != address(0));
        lockTime1 = bound(lockTime1, 1, 365 days);
        lockTime2 = bound(lockTime2, 1, 365 days);
        amount1 = bound(amount1, 1, 1000 ether);
        amount2 = bound(amount2, 1, 1000 ether);
        collectAmt = bound(collectAmt, 0, amount1 + amount2);

        // Initialize contract
        c.Initialized();
        c.SetMinSum(0);

        // Fund actor with enough ether for both puts
        vm.deal(actor, amount1 + amount2);

        // First Put at timestamp T1
        uint256 T1 = block.timestamp;
        vm.prank(actor);
        c.Put{value: amount1}(lockTime1);
        // Record the expected unlock time after first put
        uint256 expectedUnlock1 = T1 + lockTime1;

        // Warp forward so second Put has a different timestamp T2 > T1
        vm.warp(T1 + 2 days);
        uint256 T2 = block.timestamp;

        // Second Put with a different lockTime2
        vm.prank(actor);
        c.Put{value: amount2}(lockTime2);
        // Expected unlock time after second put is max(expectedUnlock1, T2 + lockTime2)
        uint256 expectedFinal = expectedUnlock1 > (T2 + lockTime2) ? expectedUnlock1 : (T2 + lockTime2);

        // Warp past expectedFinal so Collect can succeed (if enough balance)
        vm.warp(expectedFinal + 1);

        // Retrieve actual stored unlockTime from public getter
        (uint256 actualUnlock, ) = c.Acc(actor);

        // Assert: stored unlockTime must be >= expectedFinal, which is max of all (block.timestamp + _lockTime) across Puts
        assertTrue(actualUnlock >= expectedFinal);
    }
}
